SELECT departments.location, CASE WHEN departments.budget >= 3462000 THEN 'high' WHEN departments.budget >= 2029000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(employees.job_title))) AS job_title_values FROM employees RIGHT JOIN departments ON departments.id = employees.dept_id GROUP BY departments.location, CASE WHEN departments.budget >= 3462000 THEN 'high' WHEN departments.budget >= 2029000 THEN 'mid' ELSE 'low' END ORDER BY 1, job_title_values
